import React from 'react';
import SunsetPredictor from './sunsetPredictor';
import './App.css';

function App() {
  return (
    <div className="app">
      <SunsetPredictor />
      <footer className="app-footer">
        <div className="footer-content">
          <p>Sunset Predictor · Powered by ML gradient boosting models trained on real sunset data</p>
          <p className="footer-note">Backend API running at http://localhost:5001</p>
        </div>
      </footer>
    </div>
  );
}

export default App;
